WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_ct_time'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '时间限制', 'kp-eng-ct-time', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "时间限制型工程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "必须在“规定期限”内完工，倒逼效率必须提升或增加人手。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典句式：“工程必须在 30 天内交付”、“若要提前 5 天完工，需要增加多少人？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则（底线倒推）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "时间限制就是“时间定量”。因为时间定死了，必须用剩下的活去倒除剩下的时间，逼出“必须达到的最低效率”。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{必须} = \\frac{W_{剩余}}{T_{限定剩余}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[算出总量 W 和 已经消耗的 W已] --> B[W剩余 = W - W已]\nB --> C[提取题干中的死线: 原定还要干 X 天, 现要求提前 Y 天]\nC --> D[T限定剩余 = X - Y]\nD --> E[必须达到的效率 P必 = W剩余 / T限定剩余]\nE --> F[用 P必 对比 原效率, 算出需要增加的差值]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 20名工人计划 30 天修完路。修了 10 天后，接到通知必须提前 5 天完工。每名工人效率相同，问还需要增加几名工人？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋基准：每人效率为 1。W = 20 × 30 = 600。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "已完工：20人 × 10天 = 200。剩余 W余 = 400。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盘点剩余时间：原计划还要 20 天。要求提前 5 天，所以剩下的活只给 15 天！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "倒推必须效率：P必 = 400 ÷ 15 = 26.67。因为是加人，不能加半个人，必须向上取整为 27 人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算差值：现在需要 27 人，原本有 20 人。需要增加 7 人。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "除不尽时的取整方向：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "工程类增加人手/机器，只要算出来带小数（如26.2人），说明 26 个人是不够用的，必须【向上取整】到 27。千万不要用四舍五入法去舍掉小数点！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到“提前”、“按期”字眼，立刻在草稿纸上画一个闹钟图标，写下“只剩最后几天”，用倒逼法求必须效率。"}]}]}$$ AS jsonb), NULL, '时间限制的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "时间限制"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_ct_time", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
